import React from 'react';
import { Link } from 'react-router-dom';

const Home = () => (
  <div style={{ padding: 40, textAlign: 'center' }}>
    <h1>👨‍💻 My Portfolio</h1>
    <p>Hi! I'm a MERN developer.</p>

    <h2>💼 Projects</h2>
    <ul>
      <li>Project A</li>
      <li>Project B</li>
    </ul>

    <h2>🛠️ Skills</h2>
    <p>React, Node.js, MongoDB, Express</p>

    <Link to="/buy">
      <button style={{ marginTop: 20, padding: '10px 20px' }}>Buy Resume</button>
    </Link>
  </div>
);

export default Home;
